import{_ as a}from"./plugin-vue_export-helper-c27b6911.js";import{o as n,c as e,e as s}from"./app-f7ddf95e.js";const t={},i=s(`<h1 id="imagemagick-强大的命令行图像处理套件" tabindex="-1"><a class="header-anchor" href="#imagemagick-强大的命令行图像处理套件" aria-hidden="true">#</a> imagemagick（强大的命令行图像处理套件）</h1><blockquote><p>Homebrew 版本 7.1.2-9 ｜ 主页：见官方文档 ｜ 安装：<code>brew install imagemagick</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>ImageMagick 是一套功能极其强大的<strong>命令行图像处理套件</strong>，通过 <code>convert</code>、<code>magick</code>、<code>identify</code>、<code>montage</code> 等子命令对图像进行创建、转换、合成、裁剪、缩放、加水印、加边框、分析等操作，无需打开任何 GUI 即可批量处理海量图片。它解决的核心问题是&quot;用一行命令搞定图像处理的重复劳动&quot;，典型应用场景包括：批量缩放/压缩网站图片、把多种格式统一转成 JPEG/PNG/WebP、给图片加水印和缩略图、拼接对比图、读取图片元数据（EXIF/尺寸/色彩空间）等。</p><blockquote><p>注：ImageMagick 7 起，传统 <code>convert</code> 命令已迁移到统一的 <code>magick</code> 命令（<code>magick convert</code> 别名保留兼容）。本文示例以 7.x 的 <code>magick</code> 为主，同时注明旧版 <code>convert</code> 写法。</p></blockquote><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装</span>
brew <span class="token function">install</span> imagemagick

<span class="token comment"># 升级</span>
brew upgrade imagemagick

<span class="token comment"># 卸载</span>
brew uninstall imagemagick

<span class="token comment"># 验证安装成功（查看版本，应显示 7.1.2-9 之类）</span>
magick <span class="token parameter variable">--version</span>

<span class="token comment"># 查看已启用的组件（编码器、委托工具等）</span>
magick <span class="token parameter variable">-version</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>安装后 <code>magick</code>、<code>convert</code>、<code>identify</code>、<code>montage</code>、<code>mogrify</code>、<code>compare</code> 等命令即进入 PATH，直接可全局调用。ImageMagick 默认编译了大量格式支持（JPEG、PNG、GIF、TIFF、WebP、HEIC 等），无需额外安装编解码器即可覆盖绝大多数场景。</p><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><table><thead><tr><th>命令</th><th>参数说明</th><th>示例</th></tr></thead><tbody><tr><td><code>magick input.png -resize 50% out.png</code></td><td>缩放图片（支持百分比或像素尺寸）</td><td><code>magick a.png -resize 800x600 b.png</code></td></tr><tr><td><code>magick input.png -quality 80 out.jpg</code></td><td>设置 JPEG 压缩质量（0-100）</td><td><code>magick a.png -quality 80 a.jpg</code></td></tr><tr><td><code>magick input.png -crop 300x300+50+50 out.png</code></td><td>裁剪：宽x高+左偏移+上偏移</td><td><code>magick a.png -crop 100x100+0+0 b.png</code></td></tr><tr><td><code>magick input.png -rotate 90 out.png</code></td><td>旋转角度（支持顺时针正数/逆时负数）</td><td><code>magick a.png -rotate -90 b.png</code></td></tr><tr><td><code>magick input.png -format &quot;%wx%h&quot; info:</code></td><td>读取图片宽高（identify 的替代）</td><td><code>magick a.png -format &quot;%wx%h&quot; info:</code></td></tr><tr><td><code>identify input.png</code></td><td>查看图片信息（尺寸、类型、色彩）</td><td><code>identify photo.jpg</code></td></tr><tr><td><code>magick *.png -append out.png</code></td><td>垂直拼接多图；<code>+append</code> 为水平拼接</td><td><code>magick 1.png 2.png +append row.png</code></td></tr><tr><td><code>magick input.png -gravity center -pointsize 40 -annotate +0+0 &quot;文本&quot; out.png</code></td><td>在图上居中叠加文字</td><td><code>magick a.png -gravity south -annotate +0+10 &quot;© 2024&quot; b.png</code></td></tr><tr><td><code>mogrify -resize 50% *.png</code></td><td>原地批量处理（直接覆盖原文件）</td><td><code>mogrify -resize 50% -path out/ *.jpg</code></td></tr><tr><td><code>magick -size 800x600 gradient:blue-red out.png</code></td><td>生成渐变等合成图像</td><td><code>magick -size 100x100 plasma:fractal noise.png</code></td></tr></tbody></table><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-批量缩放压缩一组照片" tabindex="-1"><a class="header-anchor" href="#示例-1-批量缩放压缩一组照片" aria-hidden="true">#</a> 示例 1：批量缩放压缩一组照片</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 准备：创建测试图片（用 ImageMagick 生成几张渐变图）</span>
<span class="token function">mkdir</span> <span class="token parameter variable">-p</span> ~/imgtest <span class="token operator">&amp;&amp;</span> <span class="token builtin class-name">cd</span> ~/imgtest
magick <span class="token parameter variable">-size</span> 2000x1500 gradient:skyblue-navy p1.png
magick <span class="token parameter variable">-size</span> 1800x1200 plasma:fractal p2.png

<span class="token comment"># 批量缩放到宽 1200（保持比例），输出到 out/ 目录并转成 JPEG</span>
<span class="token function">mkdir</span> <span class="token parameter variable">-p</span> out
magick p1.png <span class="token parameter variable">-resize</span> 1200x out/p1.jpg
magick p2.png <span class="token parameter variable">-resize</span> 1200x out/p2.jpg

<span class="token comment"># 查看结果尺寸与文件大小</span>
identify out/p1.jpg out/p2.jpg
<span class="token function">ls</span> <span class="token parameter variable">-lh</span> out/
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输出形如：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>out/p1.jpg PNG 1200x900 1200x900+0+0 8-bit sRGB 96KB 0.000u 0:00.000
out/p2.jpg PNG 1200x750 1200x750+0+0 8-bit sRGB 61KB 0.000u 0:00.000
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-2-给图片加水印并导出-webp" tabindex="-1"><a class="header-anchor" href="#示例-2-给图片加水印并导出-webp" aria-hidden="true">#</a> 示例 2：给图片加水印并导出 WebP</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 准备：生成一张原图和一张半透明水印</span>
<span class="token builtin class-name">cd</span> ~/imgtest
magick <span class="token parameter variable">-size</span> 1600x1000 gradient:purple-orange photo.png
magick <span class="token parameter variable">-size</span> 400x100 xc:none <span class="token parameter variable">-fill</span> <span class="token string">&quot;rgba(255,255,255,0.6)&quot;</span> <span class="token punctuation">\\</span>
  <span class="token parameter variable">-gravity</span> center <span class="token parameter variable">-pointsize</span> <span class="token number">48</span> <span class="token parameter variable">-annotate</span> +0+0 <span class="token string">&quot;BeauXbot&quot;</span> watermark.png

<span class="token comment"># 把水印合成到原图右下角，导出为质量 85 的 WebP</span>
magick photo.png watermark.png <span class="token parameter variable">-gravity</span> southeast <span class="token parameter variable">-geometry</span> +20+20 <span class="token punctuation">\\</span>
  <span class="token parameter variable">-composite</span> <span class="token parameter variable">-quality</span> <span class="token number">85</span> photo.webp

<span class="token comment"># 校验输出</span>
identify photo.webp
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-3-读取并分析图片信息" tabindex="-1"><a class="header-anchor" href="#示例-3-读取并分析图片信息" aria-hidden="true">#</a> 示例 3：读取并分析图片信息</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 准备：随便找一张已有图片</span>
<span class="token builtin class-name">cd</span> ~/imgtest

<span class="token comment"># 完整信息</span>
identify <span class="token parameter variable">-verbose</span> photo.png

<span class="token comment"># 仅提取关键字段</span>
identify <span class="token parameter variable">-format</span> <span class="token string">&quot;尺寸: %wx%h<span class="token entity" title="\\n">\\n</span>类型: %m<span class="token entity" title="\\n">\\n</span>色彩: %[colorspace]<span class="token entity" title="\\n">\\n</span>&quot;</span> photo.png

<span class="token comment"># 用 magick 的 info: 读取尺寸（脚本友好，可赋值给变量）</span>
<span class="token assign-left variable">width</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span>magick photo.png <span class="token parameter variable">-format</span> <span class="token string">&quot;%w&quot;</span> info:<span class="token variable">)</span></span>
<span class="token assign-left variable">height</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span>magick photo.png <span class="token parameter variable">-format</span> <span class="token string">&quot;%h&quot;</span> info:<span class="token variable">)</span></span>
<span class="token builtin class-name">echo</span> <span class="token string">&quot;宽=<span class="token variable">$width</span> 高=<span class="token variable">$height</span>&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输出形如：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>尺寸: 1600x1000
类型: PNG
色彩: sRGB
宽=1600 高=1000
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-4-拼接对比图-before-after" tabindex="-1"><a class="header-anchor" href="#示例-4-拼接对比图-before-after" aria-hidden="true">#</a> 示例 4：拼接对比图（before/after）</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 准备：一张原图、一张模糊处理后的图</span>
<span class="token builtin class-name">cd</span> ~/imgtest
magick photo.png blur_photo.png

<span class="token comment"># 水平并排拼接成对比图</span>
magick photo.png blur_photo.png +append before_after.png

<span class="token comment"># 查看拼接结果</span>
identify before_after.png
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><p><strong>1. 用 <code>-path</code> 避免覆盖原文件</strong></p><p><code>mogrify</code> 默认原地覆盖。批量处理时用 <code>-path 输出目录</code> 把结果写到新目录，避免误毁原图：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>mogrify <span class="token parameter variable">-resize</span> <span class="token number">50</span>% <span class="token parameter variable">-quality</span> <span class="token number">80</span> <span class="token parameter variable">-path</span> ./thumb/ *.jpg
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><strong>2. 一次批量处理多张图 + 并发加速</strong></p><p>用 shell 循环或 <code>mogrify</code> 批量处理。多核机器上可用 <code>-define magick:threads=4</code> 或设置 <code>MAGICK_THREAD_LIMIT</code> 环境变量控制并发，避免拖垮机器：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 环境变量控制线程数（1 到 N，N 为 CPU 核心数）</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">MAGICK_THREAD_LIMIT</span><span class="token operator">=</span><span class="token number">4</span>
<span class="token comment"># 在脚本里临时限制</span>
magick <span class="token parameter variable">-limit</span> thread <span class="token number">2</span> <span class="token parameter variable">-resize</span> <span class="token number">50</span>% big.png out.png
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>3. 与脚本/其他工具搭配（批量压缩 + 排序输出）</strong></p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 把当前目录所有 JPEG 缩放到 800 宽并按文件名排序输出</span>
<span class="token function">find</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-name</span> <span class="token string">&#39;*.jpg&#39;</span> <span class="token parameter variable">-print0</span> <span class="token operator">|</span> <span class="token function">sort</span> <span class="token parameter variable">-z</span> <span class="token operator">|</span> <span class="token function">xargs</span> <span class="token parameter variable">-0</span> -I<span class="token punctuation">{</span><span class="token punctuation">}</span> magick <span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token parameter variable">-resize</span> 800x <span class="token parameter variable">-path</span> ./out/ <span class="token punctuation">{</span><span class="token punctuation">}</span>.thumb.jpg
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p><strong>4. 配置与委托（delegates）</strong></p><ul><li>环境变量：<code>MAGICK_HOME</code> 指向安装目录，<code>MAGICK_CONFIGURE_PATH</code> 指向配置文件目录，<code>MAGICK_FONT_PATH</code> 指定字体搜索路径（处理中文水印时把中文字体目录加进来可避免乱码）。</li><li>配置文件：ImageMagick 从编译时预设的路径（Homebrew 下为 <code>/usr/local/etc/ImageMagick-7</code> 或 <code>/opt/homebrew/etc/ImageMagick-7</code>）读取 <code>policy.xml</code>（安全策略）、<code>delegates.xml</code>（委托外部程序）、<code>colors.xml</code>、<code>type.xml</code> 等。查看实际路径：</li></ul><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>magick <span class="token parameter variable">-debug</span> configure info: <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span><span class="token file-descriptor important">&amp;1</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-i</span> config
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><ul><li>查看已支持的编码器与委托工具：</li></ul><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>magick <span class="token parameter variable">-list</span> <span class="token function">format</span>
magick <span class="token parameter variable">-list</span> delegate
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><p><strong>1. 7.x 的 <code>convert</code> 已变体</strong></p><p>ImageMagick 7 统一使用 <code>magick</code>，旧的 <code>convert</code> 被重命名为 <code>convert</code>（<code>magick convert</code> 别名）。Homebrew 安装 7.x 后 <code>convert</code> 命令默认仍指向 <code>magick</code> 的兼容入口，但建议新脚本直接用 <code>magick</code>，避免与系统其他软件（如 macOS 自带的 <code>convert</code>）冲突。</p><p><strong>2. <code>-crop</code> 的 <code>+x+y</code> 是&quot;原点偏移&quot;而非裁剪尺寸</strong></p><p>新手常把 <code>-crop 300x200+100+50</code> 误以为从中心裁剪。实际上 <code>+100+50</code> 表示从左上角偏移 (100,50) 处取 300x200 的区域。要&quot;从中心裁&quot;，可配合 <code>-gravity center</code>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>magick big.png <span class="token parameter variable">-gravity</span> center <span class="token parameter variable">-crop</span> 800x600+0+0 +repage out.png
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><code>+repage</code> 用来重置画布偏移，否则输出会带有虚拟画布偏移导致尺寸异常。</p><p><strong>3. 中文文字水印乱码</strong></p><p>默认字体不含中文字形。叠加中文前先指定中文字体路径，或用系统字体目录：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>magick photo.png <span class="token parameter variable">-font</span> /System/Library/Fonts/PingFang.ttc <span class="token parameter variable">-pointsize</span> <span class="token number">60</span> <span class="token punctuation">\\</span>
  <span class="token parameter variable">-gravity</span> north <span class="token parameter variable">-annotate</span> +0+20 <span class="token string">&quot;中文水印&quot;</span> out.png
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>若 <code>-font</code> 解析失败，先 <code>magick -list font | grep -i pingfang</code> 确认可用字体名。</p><p><strong>4. 大图处理的内存/磁盘开销</strong></p><p>处理超大图（几百 MB 像素）时 ImageMagick 会占用大量内存，可能 OOM 崩溃。用 <code>-limit</code> 限制资源，或改用流式处理：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>magick <span class="token parameter variable">-limit</span> memory 1GiB <span class="token parameter variable">-limit</span> map 2GiB <span class="token parameter variable">-resize</span> <span class="token number">50</span>% huge.tif out.png
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>处理大量文件时优先 <code>mogrify -path</code> 输出到独立目录，便于中途失败时重跑不覆盖原图。</p><p><strong>5. <code>-quality</code> 对 JPEG/PNG/WebP 含义不同</strong></p><ul><li>JPEG：0-100 压缩质量（数值越小体积越小、画质越差）。</li><li>PNG：无损，<code>-quality</code> 数值 0-100 实际表示 <code>zlib</code> 压缩级别（10 为 9 级压缩）与滤波器选择，默认即可。</li><li>WebP：0-100，意义同 JPEG。<br> 做&quot;压缩&quot;时先明确目标格式再设 <code>-quality</code>，否则可能无效。</li></ul><p><strong>6. 安全注意：<code>policy.xml</code> 与恶意文件</strong></p><p>ImageMagick 历史上出现过解析恶意 SVG/MVg 文件导致代码执行的漏洞。生产环境建议收紧 <code>policy.xml</code>，禁用有风险的 delegate（如 <code>MVG</code>、<code>PS</code>、<code>EPHEMERAL</code>、<code>URL</code> 读取），例如：</p><div class="language-xml line-numbers-mode" data-ext="xml"><pre class="language-xml"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>policy</span> <span class="token attr-name">domain</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>coder<span class="token punctuation">&quot;</span></span> <span class="token attr-name">rights</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>none<span class="token punctuation">&quot;</span></span> <span class="token attr-name">pattern</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>MVG<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>policy</span> <span class="token attr-name">domain</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>coder<span class="token punctuation">&quot;</span></span> <span class="token attr-name">rights</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>none<span class="token punctuation">&quot;</span></span> <span class="token attr-name">pattern</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>URL<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>policy</span> <span class="token attr-name">domain</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>coder<span class="token punctuation">&quot;</span></span> <span class="token attr-name">rights</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>none<span class="token punctuation">&quot;</span></span> <span class="token attr-name">pattern</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>EPHEMERAL<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>处理不可信来源的图片时，先用 <code>identify</code> 查看基本信息，并限制 <code>-limit</code> 资源，避免被恶意文件拖垮。</p><p><strong>7. 脚本中等待/进度输出</strong></p><p>批量任务可用 <code>-monitor</code> 显示进度，用 <code>-quiet</code> 抑制多余日志，配合 <code>set -e</code> 让脚本在出错时立即退出：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>magick <span class="token parameter variable">-monitor</span> <span class="token parameter variable">-resize</span> <span class="token number">50</span>% <span class="token parameter variable">-path</span> out/ *.jpg
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div>`,61),c=[i];function o(p,l){return n(),e("div",null,c)}const u=a(t,[["render",o],["__file","imagemagick.html.vue"]]);export{u as default};
